const FORMULA_PREFIX = /^[=+\-@\t\r]/;
export function csvCell(value){let text=String(value??'').replaceAll('"','""');if(FORMULA_PREFIX.test(text))text=`'${text}`;return `"${text}"`}
export function validateItem(item,page,rows=[]){if(!item?.name?.trim())return'이름은 필수입니다.';if(['products','orders','categories','content'].includes(page)&&!item?.sku?.trim())return'코드 또는 번호는 필수입니다.';if(Number(item.price)<0||Number(item.stock)<0)return'금액과 수량에는 음수를 입력할 수 없습니다.';if(page==='orders'&&Number(item.stock)<1)return'주문 수량은 1개 이상이어야 합니다.';const code=item?.sku?.trim().toLocaleLowerCase('ko-KR');if(code&&rows.some(row=>row.id!==item.id&&row.sku?.trim().toLocaleLowerCase('ko-KR')===code))return'동일한 코드 또는 번호가 이미 존재합니다.';if(page==='orders'&&item.shippedAt&&item.shippingDueAt&&new Date(item.shippedAt)<new Date(item.shippingDueAt))return'실제 출고일이 출고 예정일보다 빠릅니다. 날짜를 확인해 주세요.';return''}
export function getPageSlice(rows,pageIndex,pageSize){const size=Math.max(1,Number(pageSize)||20),pageCount=Math.max(1,Math.ceil(rows.length/size)),index=Math.min(Math.max(0,Number(pageIndex)||0),pageCount-1);return{pageCount,pageIndex:index,rows:rows.slice(index*size,(index+1)*size)}}
